"use client";

import {
  ColorField as AriaColorField,
  type ColorFieldProps,
  composeRenderProps,
  FieldError,
  Input,
  Label,
  Text,
} from "react-aria-components";
import { cn } from "./utils";
import {
  fieldDescriptionStyles,
  fieldErrorStyles,
  fieldInputStyles,
  fieldLabelStyles,
  fieldPaddingX,
  fieldSizeStyles,
} from "./field-styles";
import type { Size } from "./size";

export function ColorField({
  className,
  label,
  description,
  size,
  children,
  ...props
}: ColorFieldProps &
  React.RefAttributes<HTMLDivElement> & {
    label?: string;
    description?: string;
    size?: Size;
  }) {
  return (
    <AriaColorField
      {...props}
      data-slot="color-field"
      data-size={size}
      className={composeRenderProps(className, (className) =>
        cn("grid gap-2", size && fieldSizeStyles[size], className),
      )}
    >
      {children ?? (
        <>
          {label && (
            <Label data-slot="color-field-label" className={fieldLabelStyles}>
              {label}
            </Label>
          )}
          <Input
            data-slot="color-field-input"
            className={cn(fieldInputStyles, fieldPaddingX)}
          />
          {description && (
            <Text
              slot="description"
              data-slot="color-field-description"
              className={fieldDescriptionStyles}
            >
              {description}
            </Text>
          )}
          <FieldError
            data-slot="color-field-error"
            className={fieldErrorStyles}
          />
        </>
      )}
    </AriaColorField>
  );
}

"use client";

import {
  ColorSwatch as AriaColorSwatch,
  type ColorSwatchProps,
  composeRenderProps,
} from "react-aria-components";
import { cn } from "./utils";

export function ColorSwatch({ className, style, ...props }: ColorSwatchProps) {
  return (
    <AriaColorSwatch
      {...props}
      data-slot="color-swatch"
      className={composeRenderProps(className, (className) =>
        cn(
          "size-9 shrink-0 rounded-md ring-1 ring-foreground/20 ring-inset",
          className,
        ),
      )}
      style={composeRenderProps(style, (style, { color }) => ({
        background: `linear-gradient(${color}, ${color}), repeating-conic-gradient(var(--border) 0% 25%, var(--background) 0% 50%) 50% / 12px 12px`,
        ...style,
      }))}
    />
  );
}

"use client";

import {
  Dialog as AriaDialog,
  type DialogProps as AriaDialogProps,
  Popover as AriaPopover,
  type PopoverProps as AriaPopoverProps,
  composeRenderProps,
  DialogTrigger,
  type DialogTriggerProps,
  Heading,
  type HeadingProps,
  OverlayArrow,
  type OverlayArrowProps,
  Text,
  type TextProps,
} from "react-aria-components";
import { cn } from "./utils";
import { SizeProvider } from "./size";

export interface PopoverProps extends AriaPopoverProps {
  "data-slot"?: string;
}

export function PopoverTrigger(props: DialogTriggerProps) {
  return <DialogTrigger {...props} />;
}

export function Popover({
  className,
  children,
  "data-slot": dataSlot = "popover",
  arrowBoundaryOffset = 16,
  ...props
}: PopoverProps) {
  return (
    <AriaPopover
      {...props}
      data-slot={dataSlot}
      arrowBoundaryOffset={arrowBoundaryOffset}
      className={composeRenderProps(className, (className) =>
        cn(
          "group/popover max-w-[calc(100vw-2rem)] overflow-auto overscroll-contain rounded-xl border border-border bg-popover p-4 text-popover-foreground [overflow-wrap:anywhere] shadow-[var(--shadow-float)] outline-none",
          "has-[[data-slot=popover-arrow]]:flex has-[[data-slot=popover-arrow]]:flex-col has-[[data-slot=popover-arrow]]:overflow-visible",
          // React Aria sets data-entering and data-exiting once the placement is
          // known, then waits for these transitions before it unmounts the panel.
          "origin-(--trigger-anchor-point) transition-[opacity,scale,translate] duration-200 ease-out-quint",
          "placement-top:[--popover-shift:0_0.25rem] placement-bottom:[--popover-shift:0_-0.25rem] placement-left:[--popover-shift:0.25rem_0] placement-right:[--popover-shift:-0.25rem_0]",
          "entering:opacity-0 motion-safe:entering:scale-96 motion-safe:entering:[translate:var(--popover-shift)]",
          "exiting:opacity-0 exiting:duration-150 motion-safe:exiting:scale-98 motion-safe:exiting:[translate:var(--popover-shift)]",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (children) => (
        <SizeProvider size={undefined}>
          <div
            data-slot="popover-viewport"
            className="contents group-has-[[data-slot=popover-arrow]]/popover:block group-has-[[data-slot=popover-arrow]]/popover:min-h-0 group-has-[[data-slot=popover-arrow]]/popover:overflow-auto group-has-[[data-slot=popover-arrow]]/popover:overscroll-contain"
          >
            {children}
          </div>
        </SizeProvider>
      ))}
    </AriaPopover>
  );
}

export function PopoverArrow({
  className,
  ...props
}: Omit<OverlayArrowProps, "children">) {
  return (
    <OverlayArrow
      {...props}
      data-slot="popover-arrow"
      className={composeRenderProps(className, (className) =>
        cn("group/arrow", className),
      )}
    >
      <svg
        width={12}
        height={12}
        viewBox="0 0 12 12"
        aria-hidden="true"
        className="block fill-popover stroke-border group-placement-bottom/arrow:rotate-180 group-placement-left/arrow:-rotate-90 group-placement-right/arrow:rotate-90 forced-colors:fill-[Canvas] forced-colors:stroke-[CanvasText]"
      >
        <path d="M0 0 6 6 12 0" />
      </svg>
    </OverlayArrow>
  );
}

export function PopoverDialog({ className, ...props }: AriaDialogProps) {
  return (
    <AriaDialog
      {...props}
      data-slot="popover-dialog"
      className={cn("outline-none", className)}
    />
  );
}

export function PopoverTitle({ className, ...props }: HeadingProps) {
  return (
    <Heading
      {...props}
      slot="title"
      data-slot="popover-title"
      className={cn(
        "text-sm font-semibold leading-5 tracking-[-0.01em] [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function PopoverDescription({ className, ...props }: TextProps) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="popover-description"
      className={cn(
        "mt-1 block text-sm leading-5 text-muted-foreground [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function PopoverFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="popover-footer"
      className={cn("mt-4 flex flex-wrap justify-end gap-2", className)}
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import {
  ColorPicker as AriaColorPicker,
  type ColorPickerProps as AriaColorPickerProps,
  Dialog as AriaDialog,
  ColorArea,
  ColorSlider,
  ColorThumb,
  DialogTrigger,
  Label,
  SliderTrack,
} from "react-aria-components";
import { duration, easeOut } from "./motion";
import { cn } from "./utils";
import { Button } from "./button";
import { ColorField } from "./color-field";
import { ColorSwatch } from "./color-swatch";
import { fieldLabelStyles } from "./field-styles";
import { Popover } from "./popover";

const colorThumbStyles =
  "size-6 rounded-full border-2 border-white shadow-[var(--shadow-card)] ring-1 ring-black/50 outline-none outline-offset-4 outline-transparent transition-[outline-color,outline-offset] duration-150 ease-out-quint focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-offset-2 focus-visible:outline-ring motion-reduce:outline-offset-2";

export interface ColorPickerProps
  extends Omit<AriaColorPickerProps, "children"> {
  label?: string;
  children?: AriaColorPickerProps["children"];
}

export function ColorPicker({
  label = "Choose color",
  children,
  ...props
}: ColorPickerProps) {
  return (
    <AriaColorPicker {...props}>
      {children ?? (
        <DialogTrigger>
          <Button variant="outline" data-slot="color-picker-trigger">
            <ColorSwatch className="size-6" />
            {label}
          </Button>
          <Popover
            data-slot="color-picker-popover"
            placement="bottom start"
            className="w-64 p-3"
          >
            <AriaDialog
              aria-label={`${label} controls`}
              className="grid gap-3 outline-none"
            >
              <ColorArea
                data-slot="color-picker-area"
                colorSpace="hsb"
                xChannel="saturation"
                yChannel="brightness"
                aria-label="Saturation and brightness"
                className="aspect-square w-full rounded-lg ring-1 ring-inset ring-foreground/20"
              >
                <ColorThumb
                  data-slot="color-picker-area-thumb"
                  className={colorThumbStyles}
                >
                  {({ isDragging }) => (
                    <ThumbDragRing isDragging={isDragging} />
                  )}
                </ColorThumb>
              </ColorArea>
              <ColorSlider
                data-slot="color-picker-hue"
                colorSpace="hsb"
                channel="hue"
                className="grid gap-2"
              >
                <Label className={fieldLabelStyles}>Hue</Label>
                <SliderTrack className="relative h-5 rounded-full ring-1 ring-inset ring-foreground/20">
                  <ColorThumb
                    data-slot="color-picker-hue-thumb"
                    className={cn(colorThumbStyles, "top-1/2")}
                  >
                    {({ isDragging }) => (
                      <ThumbDragRing isDragging={isDragging} />
                    )}
                  </ColorThumb>
                </SliderTrack>
              </ColorSlider>
              <ColorField label="Hex" />
            </AriaDialog>
          </Popover>
        </DialogTrigger>
      )}
    </AriaColorPicker>
  );
}

function ThumbDragRing({ isDragging }: { isDragging: boolean }) {
  const reduceMotion = useReducedMotion();
  return (
    <motion.span
      aria-hidden="true"
      className="pointer-events-none absolute -inset-1 rounded-full ring-2 ring-primary/60"
      initial={false}
      animate={{ opacity: isDragging ? 1 : 0, scale: isDragging ? 1 : 0.85 }}
      transition={{ duration: reduceMotion ? 0 : duration.fast, ease: easeOut }}
    />
  );
}
